/// <summary>
/// to change the item site level field called Item status to 'Active', 'Discontinued', or 'Deleted'.
/// MPJ_22974_BMSProductMDRItemStatusAndPackChange
/// </summary>
class METChangeItemStatusService
{
    InventParameters InventParameters = InventParameters::find();
}

Method.Source:
    /// <summary>
    /// to change the item site level field called Item status to 'Active', 'Discontinued', or 'Deleted'.
    /// MPJ_22974_BMSProductMDRItemStatusAndPackChange    
    /// </summary>
    /// <param name = "_metChangeItemStatusContract">data contract </param>
    public void changeStatus(METChangeItemStatusContract _metChangeItemStatusContract)
    {
        #OCCRetryCount
        Query                   query;
        QueryBuildDataSource    qbds, qbdsInventDim;
        QueryBuildRange         qbrItem, qbrSiteId, qbrItemStatus, qbrDiscontinueDate;
        
        try
        {
            ttsbegin;
            query   = new Query();
            ItemId  itemId  = _metChangeItemStatusContract.parmItemId();
            InventSiteId siteId  = _metChangeItemStatusContract.parmInventSiteId();
            qbds = query.addDataSource(tableNum(METInventItemOrderSetup));

            if (itemId != '')
            {
                qbrItem = qbds.addRange(fieldNum(METInventItemOrderSetup, ItemId));
                qbrItem.value(queryValue(itemId));
            }

            if (siteId != '')
            {
                qbdsInventDim = qbds.addDataSource(tablenum(InventDim));
                qbdsInventDim.relations(true);
                qbrSiteId = qbdsInventDim.addRange(fieldNum(InventDim, InventSiteId));
                qbrSiteId.value(queryValue(siteId));
            }
            if (_metChangeItemStatusContract.parmMETItemStatus() == METItemStatusTable::findByStatus(METItemsStatus::Active).ItemStatus)
            {            
                qbrItemStatus = qbds.addRange(fieldNum(METInventItemOrderSetup, ItemStatus));
                qbrItemStatus.value(strFmt('((%1 == "%2") || (%1 == ""))', fieldstr(METInventItemOrderSetup, ItemStatus),
                    METItemStatusTable::findByStatus(METItemsStatus::New).ItemStatus));
            }           

            QueryRun                queryRun = new QueryRun(query);

            if (_metChangeItemStatusContract.parmMETItemStatus() == METConstants::Active)
            {
                this.changeStatusToActive(queryRun);            
            }
            else if (_metChangeItemStatusContract.parmMETItemStatus() == METConstants::Discontinued)
            {
                this.changeStatusToDiscontinued(queryRun, _metChangeItemStatusContract);
            }
            else if (_metChangeItemStatusContract.parmMETItemStatus() == METConstants::Deleted)
            {
                this.changeStatusToDeleted(queryRun);
            }
            ttscommit;
        }
        catch (Exception::Deadlock)
        {
            if (xSession::currentRetryCount() >= #RetryNum)
            {
                throw Exception::Deadlock;
            }
            else
            {
                retry;
            }
        }
        catch (Exception::UpdateConflict)
        {
            if (appl.ttsLevel() == 0)
            {
                if (xSession::currentRetryCount() >= #RetryNum)
                {
                    throw Exception::UpdateConflictNotRecovered;
                }
                else
                {
                    retry;
                }
            }
            else
            {
                throw Exception::UpdateConflict;
            }
        }
        catch
        {
            throw error("@MET:UnhandledError");
        }
        
    }

    /// <summary>
    /// Delete change status
    /// </summary>
    /// <param name = "_queryRun">QueryRun</param>
    private void changeStatusToDeleted(QueryRun _queryRun)
    {
        while(_queryRun.next())
        {
            InventLocation inventLocation, inventLocationNDC;
            METInventItemOrderSetup metInventItemOrderSetup;
            METReqItemTableInventDimView metReqItemTableInventDimView;

            metInventItemOrderSetup = _queryRun.get(tableNum(METInventItemOrderSetup));

            InventSite inventSite = InventSite::find(InventDim::find(metInventItemOrderSetup.InventDimId).InventSiteId);

            while select ItemId, CovInventDimId, ReqPOType, InventLocationIdReqMain, VendId, ReqItemTableRecId, InventLocationId
                from metReqItemTableInventDimView
                where metReqItemTableInventDimView.ItemId == metInventItemOrderSetup.ItemId
                && metReqItemTableInventDimView.InventSiteId == inventSite.SiteId
                && metReqItemTableInventDimView.ReqPOType == ReqPOType::Purch
                && metReqItemTableInventDimView.METInterCompanySourced != NoYes::Yes
            {
                //When planned order type is Purch
                if ( metInventItemOrderSetup.ItemStatus == METConstants::Discontinued
                    && metInventItemOrderSetup.DiscontinueDate <= DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone()))
                {
                    if ((this.checkIfItemIsTemp(metReqItemTableInventDimView.ItemId) 
                        && this.checkIfItemIsTempItemForPackChange(metReqItemTableInventDimView.ItemId)) 
                        || (this.checkIfItemIsChild(metReqItemTableInventDimView.ItemId, inventSite.SiteId)))
                    {
                        continue;
                    }

                    select firstonly METNDCWarehouse, InventSiteId, InventLocationId from inventLocation
                        where inventLocation.InventLocationId == metReqItemTableInventDimView.InventLocationId;

                    if (inventLocation.METNDCWarehouse) // If NDC warehouse, 
                    {
                        if (this.changeStatusToDeleted_ValidateNDC(metReqItemTableInventDimView.ReqItemTableRecId, metReqItemTableInventDimView.ItemId)) //check for all NDC and if site is NDC then validate all sites if any of site
                        {
                            while select RecId, InventSiteId, InventLocationId
                            from inventLocationNDC
                            where inventLocationNDC.METNDCWarehouse == NoYes::Yes
                            {
                                this.changeStatusToDeleted_ValidateAndDelete(inventLocationNDC, metInventItemOrderSetup, metReqItemTableInventDimView.ReqItemTableRecId, false, true);
                            }
                        }
                    }
                    else // Non NDC site
                    {
                        this.changeStatusToDeleted_ValidateAndDelete(inventLocation, metInventItemOrderSetup, metReqItemTableInventDimView.ReqItemTableRecId, false, true);
                    }               

                }
            }
            while select ItemId, CovInventDimId, ReqPOType, InventLocationIdReqMain, VendId, ReqItemTableRecId, InventLocationId
                from metReqItemTableInventDimView
                where metReqItemTableInventDimView.ItemId == metInventItemOrderSetup.ItemId
                && metReqItemTableInventDimView.InventSiteId == inventSite.SiteId
                && metReqItemTableInventDimView.ReqPOType == ReqPOType::Transfer
            {
                //when planned order is Transfer
                if (metInventItemOrderSetup.ItemStatus == METConstants::Discontinued
                    && metInventItemOrderSetup.DiscontinueDate <= DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone()))
                 {

                    if (this.checkIfItemIsTemp(metInventItemOrderSetup.ItemId) && this.checkIfItemIsTempItemForPackChange(metInventItemOrderSetup.ItemId)
                        || (this.checkIfItemIsChild(metInventItemOrderSetup.ItemId, inventSite.SiteId))
                        || (!this.checkIfSourceSiteWithItemStatusNotDiscontinued(metInventItemOrderSetup)))
                    {
                        continue;
                    }

                    select firstonly METNDCWarehouse, InventSiteId, InventLocationId from inventLocation
                        where inventLocation.InventLocationId == metReqItemTableInventDimView.InventLocationId;

                    if (inventLocation.METNDCWarehouse) //If NDC warehouse
                    {
                        if (this.changeStatusToDeleted_ValidateNDC(metReqItemTableInventDimView.ReqItemTableRecId, metReqItemTableInventDimView.ItemId)) //check for all NDC and if site is NDC then validate all sites if any of site
                        {
                            while select RecId, InventSiteId, InventLocationId
                            from inventLocationNDC
                            where inventLocationNDC.METNDCWarehouse == NoYes::Yes
                            {
                                this.changeStatusToDeleted_ValidateAndDelete(inventLocationNDC, metInventItemOrderSetup, metReqItemTableInventDimView.ReqItemTableRecId, false);
                            }
                        }
                    }
                    else // Non NDC site
                    {
                        this.changeStatusToDeleted_ValidateAndDelete(inventLocation, metInventItemOrderSetup, metReqItemTableInventDimView.ReqItemTableRecId, false);
                    }
                }               
            }
            while select ItemId, CovInventDimId, ReqPOType, InventLocationIdReqMain, VendId, ReqItemTableRecId, InventLocationId, VendIntercompanyWarehouse
                from metReqItemTableInventDimView
                where metReqItemTableInventDimView.ItemId == metInventItemOrderSetup.ItemId
                && metReqItemTableInventDimView.InventSiteId == inventSite.SiteId
                && metReqItemTableInventDimView.ReqPOType == ReqPOType::Purch
                && metReqItemTableInventDimView.METInterCompanySourced == NoYes::Yes
            {
                //when planned order is PO (Intercompany)
                if (metInventItemOrderSetup.ItemStatus == METConstants::Discontinued
                && metInventItemOrderSetup.DiscontinueDate <= DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone())
                )
                {
                    if ((this.checkIfItemIsTemp(metInventItemOrderSetup.ItemId) && this.checkIfItemIsTempItemForPackChange(metInventItemOrderSetup.ItemId))
                        || (this.checkIfItemIsChild(metInventItemOrderSetup.ItemId, inventSite.SiteId))
                        || (!this.checkIfSourceSiteWithItemStatusNotDiscontinued_IntCom(metInventItemOrderSetup, metReqItemTableInventDimView))
                        )
                    {
                        continue;
                    }

                    select firstonly METNDCWarehouse, InventSiteId, InventLocationId from inventLocation
                        where inventLocation.InventLocationId == metReqItemTableInventDimView.InventLocationId;

                    if (inventLocation.METNDCWarehouse) // If NDC warehouse
                    {
                        if (this.changeStatusToDeleted_ValidateNDC(metReqItemTableInventDimView.ReqItemTableRecId, metReqItemTableInventDimView.ItemId)) //check for all NDC and if site is NDC then validate all sites if any of site
                        {
                            while select RecId, InventSiteId, InventLocationId
                            from inventLocationNDC
                            where inventLocationNDC.METNDCWarehouse == NoYes::Yes
                            {
                                this.changeStatusToDeleted_ValidateAndDelete(inventLocationNDC, metInventItemOrderSetup, metReqItemTableInventDimView.ReqItemTableRecId, false);
                            }
                        }
                    }
                    else // Non NDC site
                    {
                        this.changeStatusToDeleted_ValidateAndDelete(inventLocation, metInventItemOrderSetup, metReqItemTableInventDimView.ReqItemTableRecId, false);
                    }
                }
            }

        }
    }

    /// <summary>
    /// Validate the record and status to Delete
    /// </summary>
    /// <param name = "_inventLocation">InventLocation</param>
    /// <param name = "_metInventItemOrderSetup">METInventItemOrderSetup</param>
    /// <param name = "_reqItemTableRecId">RecId</param>
    /// <param name = "_calledFromTransferSite">boolean</param>
    /// <param name = "_checkForTransferOrder">boolean</param>
    private void changeStatusToDeleted_ValidateAndDelete(InventLocation _inventLocation, METInventItemOrderSetup _metInventItemOrderSetup, RecId _reqItemTableRecId, boolean _calledFromTransferSite, boolean _checkForTransferOrder = false)
    {
        if (this.changeStatusToDeleted_Validate(_inventLocation, _reqItemTableRecId, _metInventItemOrderSetup.ItemId)) // Validate main Item
        {
            if (_metInventItemOrderSetup.TempItemPackChg
                && this.changeStatusToDeleted_Validate(_inventLocation, _reqItemTableRecId, _metInventItemOrderSetup.TempItemPackChg) ) // If main Item contains Temp Item and validate temp Item
            {               
                if (_calledFromTransferSite)
                {
                    METInventItemOrderSetup metInventItemOrderSetupTransferSite, metInventItemOrderSetupTransferSiteTempItem, metInventItemOrderSetupMainSite;

                    select firstonly metInventItemOrderSetupMainSite
                        where metInventItemOrderSetupMainSite.SiteId == _inventLocation.InventSiteId
                        && metInventItemOrderSetupMainSite.ItemId == _metInventItemOrderSetup.ItemId;

                    select firstonly forupdate metInventItemOrderSetupTransferSite
                        where metInventItemOrderSetupTransferSite.SiteId == _metInventItemOrderSetup.SiteId
                        && metInventItemOrderSetupTransferSite.ItemId == _metInventItemOrderSetup.ItemId
                        && metInventItemOrderSetupTransferSite.ItemStatus != METConstants::Deleted
                        && metInventItemOrderSetupTransferSite.ItemStatus != METConstants::Discontinued;

                    if(metInventItemOrderSetupMainSite && metInventItemOrderSetupTransferSite)
                    {
                        this.copyDelReasonAndVendReplacementFromSourceToTransferSiteMain(metInventItemOrderSetupMainSite, metInventItemOrderSetupTransferSite);
                    }

                    select firstonly forupdate metInventItemOrderSetupTransferSiteTempItem
                        where metInventItemOrderSetupTransferSiteTempItem.SiteId == metInventItemOrderSetupTransferSite.SiteId
                        && metInventItemOrderSetupTransferSiteTempItem.ItemId == metInventItemOrderSetupTransferSite.TempItemPackChg
                        && metInventItemOrderSetupTransferSiteTempItem.ItemStatus != METConstants::Deleted
                        && metInventItemOrderSetupTransferSiteTempItem.ItemStatus != METConstants::Discontinued;
                    
                    if(metInventItemOrderSetupMainSite && metInventItemOrderSetupTransferSiteTempItem)
                    {
                        this.copyDelReasonAndVendReplacementFromSourceToTransferSiteMain(metInventItemOrderSetupMainSite, metInventItemOrderSetupTransferSiteTempItem);
                    }
                }
                this.updateStatusToDeletedMain(_metInventItemOrderSetup.ItemId, InventDim::find(_metInventItemOrderSetup.InventDimId), _metInventItemOrderSetup); // Delete status to Main item
                this.updateStatusToDeletedMain(_metInventItemOrderSetup.TempItemPackChg, InventDim::find(_metInventItemOrderSetup.InventDimId), METInventItemOrderSetup::findByItemAndSite(_metInventItemOrderSetup.TempItemPackChg, _metInventItemOrderSetup.SiteId)); // Delete status to Temp item
            }
            else if (!_metInventItemOrderSetup.TempItemPackChg) // If no temp item found
            {
                if (_calledFromTransferSite)
                {
                    METInventItemOrderSetup metInventItemOrderSetupMainSite;

                    select firstonly metInventItemOrderSetupMainSite
                        where metInventItemOrderSetupMainSite.SiteId == _inventLocation.InventSiteId
                        && metInventItemOrderSetupMainSite.ItemId == _metInventItemOrderSetup.ItemId;

                    this.copyDelReasonAndVendReplacementFromSourceToTransferSiteMain(metInventItemOrderSetupMainSite,_metInventItemOrderSetup);
                }
                this.updateStatusToDeletedMain(_metInventItemOrderSetup.ItemId, InventDim::find(_metInventItemOrderSetup.InventDimId), _metInventItemOrderSetup); // Delete status to Main item
            }

            if (_checkForTransferOrder)
            {
                this.checkAndDeleteIfItemIsTOInOtherSites(_inventLocation, _metInventItemOrderSetup);
                this.checkAndDeleteIfItemIsTOInOtherSites_IntComp(_inventLocation, _metInventItemOrderSetup);
            }
        }
    }

    /// <summary>
    /// Check if Transfer order is present or not
    /// </summary>
    /// <param name = "_inventLocation">InventLocation</param>
    /// <param name = "_metInventItemOrderSetup">METInventItemOrderSetup</param>
    private void checkAndDeleteIfItemIsTOInOtherSites(InventLocation _inventLocation, METInventItemOrderSetup _metInventItemOrderSetup )
    {
        ReqItemTable reqItemTableTOInOtherSite;
        METInventItemOrderSetup metInventItemOrderSetupTransferSite, metInventItemOrderSetupTransferSiteTempItem;

        // Check if Item is a transferorder in other sites
        while select ItemId, CovInventDimId, ReqPOType, InventLocationIdReqMain, VendId, RecId 
            from reqItemTableTOInOtherSite
            where reqItemTableTOInOtherSite.ItemId == _metInventItemOrderSetup.ItemId &&
            reqItemTableTOInOtherSite.InventLocationIdReqMain == _inventLocation.InventLocationId &&
            reqItemTableTOInOtherSite.ReqPOType == ReqPOType::Transfer
        {
            InventSite inventSite = InventSite::find(InventDim::find(reqItemTableTOInOtherSite.CovInventDimId).InventSiteId);

            select firstonly metInventItemOrderSetupTransferSite
                where metInventItemOrderSetupTransferSite.SiteId == inventSite.SiteId
                && metInventItemOrderSetupTransferSite.ItemId == _metInventItemOrderSetup.ItemId
                && metInventItemOrderSetupTransferSite.ItemStatus != METConstants::Deleted;

            if (inventSite.METNDCSite && metInventItemOrderSetupTransferSite && metInventItemOrderSetupTransferSite.ItemStatus != METConstants::Discontinued)
            {                
                this.copyDelReasonAndVendReplacementFromSourceToTransferSite(_metInventItemOrderSetup, metInventItemOrderSetupTransferSite);
                METInventItemOrderSetup::updateChildItemSiteStatusToDiscontinue(metInventItemOrderSetupTransferSite.ItemId, metInventItemOrderSetupTransferSite.SiteId, metInventItemOrderSetupTransferSite);
                if (metInventItemOrderSetupTransferSite.TempItemPackChg)
                {
                    select firstonly metInventItemOrderSetupTransferSiteTempItem
                        where metInventItemOrderSetupTransferSiteTempItem.SiteId == metInventItemOrderSetupTransferSite.SiteId
                        && metInventItemOrderSetupTransferSiteTempItem.ItemId == metInventItemOrderSetupTransferSite.TempItemPackChg
                        && metInventItemOrderSetupTransferSiteTempItem.ItemStatus != METConstants::Deleted
                        && metInventItemOrderSetupTransferSiteTempItem.ItemStatus != METConstants::Discontinued;

                    if (metInventItemOrderSetupTransferSiteTempItem)
                    {
                        this.copyDelReasonAndVendReplacementFromSourceToTransferSite(metInventItemOrderSetupTransferSite, metInventItemOrderSetupTransferSiteTempItem);
                        METInventItemOrderSetup::updateChildItemSiteStatusToDiscontinue(metInventItemOrderSetupTransferSiteTempItem.ItemId, metInventItemOrderSetupTransferSiteTempItem.SiteId, metInventItemOrderSetupTransferSiteTempItem);
                    }

                }
            }
            else if (!inventSite.METNDCSite && metInventItemOrderSetupTransferSite)
            {
                InventDim       inventDimLoc = InventDim::find(reqItemTableTOInOtherSite.CovInventDimId);
                InventLocation  invnetLocationLoc;

                select firstonly METNDCWarehouse, InventSiteId, InventLocationId from invnetLocationLoc
                    where invnetLocationLoc.InventLocationId == inventDimLoc.InventLocationId
                    && invnetLocationLoc.InventSiteId == inventDimLoc.InventSiteId;
                
                if (invnetLocationLoc)
                {
                    this.changeStatusToDeleted_ValidateAndDelete(invnetLocationLoc, metInventItemOrderSetupTransferSite, reqItemTableTOInOtherSite.RecId, true);
                }
            }
        }
       
    }

    /// <summary>
    /// Check if Transfer order is present or not for Intercompany
    /// </summary>
    /// <param name = "_inventLocation">Warehouse table</param>
    /// <param name = "_metInventItemOrderSetup">METInventItemOrderSetup table</param>
    private void checkAndDeleteIfItemIsTOInOtherSites_IntComp(InventLocation _inventLocation, METInventItemOrderSetup _metInventItemOrderSetup )
    { 
        DataAreaId currentLegalEntity = curExt();
        changecompany(inventParameters.METInterCompanyPurchaseLegalEntity)
        {
            METInventItemOrderSetup metInventItemOrderSetupTransferSite, metInventItemOrderSetupTransferSiteTempItem;
            METReqItemTableInventDimView metReqItemTableInventDimView;

            // Check if Item is a transferorder in other sites            
            while select ItemId, CovInventDimId, ReqPOType, InventLocationIdReqMain, VendId, RecId, VendIntercompanyWarehouse
                from metReqItemTableInventDimView
                where metReqItemTableInventDimView.ItemId == _metInventItemOrderSetup.ItemId
                && metReqItemTableInventDimView.ReqPOType == ReqPOType::Purch
                && metReqItemTableInventDimView.METInterCompanySourced == NoYes::Yes
            {                
                if (this.getSiteFromCurrentLegalEntity(metReqItemTableInventDimView.VendIntercompanyWarehouse, currentLegalEntity)  == _inventLocation.InventSiteId)
                {
                    InventSite inventSite = InventSite::find(InventDim::find(metReqItemTableInventDimView.CovInventDimId).InventSiteId);

                    select firstonly forupdate metInventItemOrderSetupTransferSite
                        where metInventItemOrderSetupTransferSite.SiteId == inventSite.SiteId
                        && metInventItemOrderSetupTransferSite.ItemId == _metInventItemOrderSetup.ItemId;

                    if (inventSite.METNDCSite && metInventItemOrderSetupTransferSite && (metInventItemOrderSetupTransferSite.ItemStatus != METConstants::Deleted || metInventItemOrderSetupTransferSite.ItemStatus != METConstants::Discontinued))
                    {
                        this.copyDelReasonAndVendReplacementFromSourceToTransferSiteMain(_metInventItemOrderSetup, metInventItemOrderSetupTransferSite);
                        if (metInventItemOrderSetupTransferSite.TempItemPackChg)
                        {
                            select firstonly forupdate metInventItemOrderSetupTransferSiteTempItem
                                where metInventItemOrderSetupTransferSiteTempItem.SiteId == metInventItemOrderSetupTransferSite.SiteId
                                && metInventItemOrderSetupTransferSiteTempItem.ItemId == metInventItemOrderSetupTransferSite.TempItemPackChg;

                            if(metInventItemOrderSetupTransferSiteTempItem.ItemStatus != METConstants::Deleted ||  metInventItemOrderSetupTransferSiteTempItem.ItemStatus != METConstants::Discontinued)
                            {
                                this.copyDelReasonAndVendReplacementFromSourceToTransferSiteMain(metInventItemOrderSetupTransferSite, metInventItemOrderSetupTransferSiteTempItem);
                            }

                        }
                    }
                    else if (!inventSite.METNDCSite && metInventItemOrderSetupTransferSite)
                    {
                        this.changeStatusToDeleted_ValidateAndDelete(_inventLocation, metInventItemOrderSetupTransferSite, metReqItemTableInventDimView.ReqItemTableRecId, true);
                    }

                }
            }
        }        
       
    }

    private InventSiteId getSiteFromCurrentLegalEntity(InventLocationId _inventLocationId, DataAreaId _searchLegalEntity)
    {
        InventLocationId    inventLocationId;

        changecompany(_searchLegalEntity)
        {
            InventLocation inventLocation;

            select firstonly InventSiteId from inventLocation
                where inventLocation.InventLocationId == _inventLocationId;

            inventLocationId = inventLocation.InventSiteId;
        }

        return inventLocationId;
        
    }

    /// <summary>
    /// Copy reason code, vend replacement and update to discontinue
    /// </summary>
    /// <param name = "_metInventItemOrderSetupSource">METInventItemOrderSetup</param>
    /// <param name = "_metInventItemOrderSetupDestination">METInventItemOrderSetup</param>
    private void copyDelReasonAndVendReplacementFromSourceToTransferSiteMain(METInventItemOrderSetup _metInventItemOrderSetupSource, METInventItemOrderSetup _metInventItemOrderSetupDestination)
    {
        if(_metInventItemOrderSetupDestination)
        {
            this.copyDelReasonAndVendReplacementFromSourceToTransferSite(_metInventItemOrderSetupSource,_metInventItemOrderSetupDestination);

            METSalesItemSubstitutionParentChild childItems;
            METInventItemOrderSetup metInventItemOrderSetupForChildItems;
                                                        
            while select ChildItemID, InventSiteId from childItems
                join forupdate metInventItemOrderSetupForChildItems
                where childItems.ParentItemID == _metInventItemOrderSetupDestination.ItemId
                && childItems.InventSiteId == _metInventItemOrderSetupDestination.SiteId
                && metInventItemOrderSetupForChildItems.ItemId == childItems.ChildItemID
                && metInventItemOrderSetupForChildItems.SiteId == childItems.InventSiteId
            {
                this.copyDelReasonAndVendReplacementFromSourceToTransferSite(_metInventItemOrderSetupDestination,metInventItemOrderSetupForChildItems);
            }
        }
    }

    /// <summary>
    /// Copy deletion reason and Vend replacement
    /// </summary>
    /// <param name = "_metInventItemOrderSetupSource">METInventItemOrderSetup</param>
    /// <param name = "_metInventItemOrderSetupDestination">METInventItemOrderSetup</param>
    private void copyDelReasonAndVendReplacementFromSourceToTransferSite(METInventItemOrderSetup _metInventItemOrderSetupSource, METInventItemOrderSetup _metInventItemOrderSetupDestination)
    {
        InventItemPurchSetup inventItemPurchSetup = InventItemPurchSetup::find(_metInventItemOrderSetupDestination.ItemId,_metInventItemOrderSetupDestination.InventDimId);

        if (_metInventItemOrderSetupDestination)
        {
            ttsbegin;
            _metInventItemOrderSetupDestination.selectForUpdate(true);
            _metInventItemOrderSetupDestination.ItemStatus = METConstants::Discontinued;
            _metInventItemOrderSetupDestination.DiscontinueDate = DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone());
            _metInventItemOrderSetupDestination.VendReplacement = _metInventItemOrderSetupSource.VendReplacement;
            _metInventItemOrderSetupDestination.DeletionReason = _metInventItemOrderSetupSource.DeletionReason;
            _metInventItemOrderSetupDestination.update();
            ttscommit;
        }

        if (inventItemPurchSetup)
        {
            ttsbegin;
            inventItemPurchSetup.selectForUpdate(true);
            inventItemPurchSetup.Stopped = true;
            inventItemPurchSetup.update();
            ttscommit;
        }

    }

    /// <summary>
    /// Check if source site with item status is not discontinued 
    /// </summary>
    /// <param name = "_metInventItemOrderSetup">METInventItemOrderSetup</param>
    /// <returns>boolean</returns>
    private boolean checkIfSourceSiteWithItemStatusNotDiscontinued(METInventItemOrderSetup _metInventItemOrderSetup)
    {
        ReqItemTable reqItemTableSourceSite;
        InventDim   inventDimSourceSite;
        InventLocation inventLocation;
        METInventItemOrderSetup metInventItemOrderSetupDiscontinued;
        boolean ret;

        select firstonly ItemId,CovInventDimId,ReqPOType,InventLocationIdReqMain, VendId from reqItemTableSourceSite
                    exists join inventDimSourceSite
                    where reqItemTableSourceSite.ItemId == _metInventItemOrderSetup.ItemId   &&
                    reqItemTableSourceSite.CovInventDimId == inventDimSourceSite.inventDimId &&
                    inventDimSourceSite.InventSiteId == _metInventItemOrderSetup.SiteId;

        select firstonly InventSiteId, RecId from inventLocation
                            where inventLocation.InventLocationId == reqItemTableSourceSite.InventLocationIdReqMain;

        if (inventLocation)
        {
            select firstonly RecId
                from metInventItemOrderSetupDiscontinued
                where metInventItemOrderSetupDiscontinued.ItemId  == _metInventItemOrderSetup.ItemId  &&
                metInventItemOrderSetupDiscontinued.SiteId        == inventLocation.InventSiteId      &&
                metInventItemOrderSetupDiscontinued.ItemStatus    !=  METConstants::Discontinued;

            if (metInventItemOrderSetupDiscontinued)
            {
                return true;
            }
        }

        return ret;
    }

    /// <summary>
    /// Check if source site with item status is not discontinued
    /// </summary>
    /// <param name = "_metInventItemOrderSetup">METInventItemOrderSetup table</param>
    /// <param name = "_vendAccount">Vendor account</param>
    /// <returns>boolean</returns>
    private boolean checkIfSourceSiteWithItemStatusNotDiscontinued_IntCom(METInventItemOrderSetup _metInventItemOrderSetup, MetReqItemTableInventDimView _metReqItemTableInventDimView)
    {  
        boolean ret;

        changecompany(inventParameters.METInterCompanyPurchaseLegalEntity)
        {
            InventLocation inventLocation;
            METInventItemOrderSetup metInventItemOrderSetupDiscontinued;

            select firstonly InventSiteId, RecId from inventLocation
                where inventLocation.InventLocationId == _metReqItemTableInventDimView.VendIntercompanyWarehouse;

            if (inventLocation)
            {
                select firstonly RecId
                from metInventItemOrderSetupDiscontinued
                    where metInventItemOrderSetupDiscontinued.ItemId  == _metInventItemOrderSetup.ItemId
                    && metInventItemOrderSetupDiscontinued.SiteId == inventLocation.InventSiteId
                    && metInventItemOrderSetupDiscontinued.ItemStatus !=  METConstants::Discontinued;

                if (metInventItemOrderSetupDiscontinued)
                {
                    ret = true;
                }
            }
        }

        return ret;
    }

    /// <summary>
    /// Validate Delete batch data
    /// </summary>
    /// <param name = "_inventLocation">InventLocation</param>
    /// <param name = "_reqItemTableRecId">RecId</param>
    /// <param name = "_itemId">ItemId</param>
    /// <returns>boolean</returns>
    private boolean changeStatusToDeleted_Validate(InventLocation _inventLocation, RecId _reqItemTableRecId, ItemId _itemId)
    {
        boolean ret = true;

        InventWarehouseOnHandIncludingCWItemAggregatedView  inventOnHandView;
        InventWarehouseOnHandIncludingCatchWeightItemEntity inventOnHandEntity;
        METReqItemTable metReqItemTable = METReqItemTable::find(_reqItemTableRecId);

        select firstonly AvailableOnHandQuantityMapped, PdsCWAvailOnHandQuantityMapped,
            OrderedQuantityMapped, PdsCWOrderedQuantityMapped,
            ReservedOnHandQuantityMapped, ReservedOrderedQuantityMapped, PdsCWReservOnHandQuantityMapped
                from inventOnHandView
                where inventOnHandView.ItemNumber == _itemId
                    && inventOnHandView.InventorySiteId == _inventLocation.InventSiteId
                    && inventOnHandView.InventoryWarehouseId == _inventLocation.InventLocationId;

        if (inventOnHandView.AvailableOnHandQuantityMapped || inventOnHandView.PdsCWAvailOnHandQuantityMapped)
        {
            ret = checkFailed(strfmt("@MET:OnHandValidation", _itemId,_inventLocation.InventSiteId, _inventLocation.InventLocationId));
        }
        if (inventOnHandView.OrderedQuantityMapped || inventOnHandView.PdsCWOrderedQuantityMapped || inventOnHandView.ReservedOnHandQuantityMapped ||
                inventOnHandView.PdsCWReservOnHandQuantityMapped || inventOnHandView.ReservedOrderedQuantityMapped)
        {
            ret = checkFailed(strfmt("@MET:OpenPOTOValidation", _itemId,_inventLocation.InventSiteId, _inventLocation.InventLocationId)) && ret;
        }
        if (metReqItemTable.SlotLoc1Area)
        {
            ret = checkFailed(strfmt("@MET:SlotLocation1Validation", _itemId,_inventLocation.InventSiteId, _inventLocation.InventLocationId)) && ret;
        }
        if (metReqItemTable.SlotLoc2Area)
        {
            ret = checkFailed(strfmt("@MET:SlotLocation2Validation",_itemId,_inventLocation.InventSiteId, _inventLocation.InventLocationId))&& ret;
        }

        return ret;
    }

    /// <summary>
    /// To change the item site level field called Item status to 'Deleted'.
    /// </summary>
    /// <param name = "_itemId">Item Id</param>
    /// <param name = "_inventDim">Invent Dim</param>
    /// <param name = "_metInventItemOrderSetup">METInventItemOrderSetup table</param>
    private void updateStatusToDeletedMain(ItemId    _itemId, InventDim _inventDim, METInventItemOrderSetup _metInventItemOrderSetup)
    {
        if (_itemId)
        {
            this.updateStatusToDeleted(_metInventItemOrderSetup, _inventDim.inventDimId);
                                
            METSalesItemSubstitutionParentChild childItems;
                                                            
            while select ChildItemID, InventSiteId from childItems
                    where childItems.ParentItemID == _itemId
                    && childItems.InventSiteId == _inventDim.InventSiteId
            {
                METInventItemOrderSetup metInventItemOrderSetupForChildItems;
                                    
                select firstonly metInventItemOrderSetupForChildItems
                        where metInventItemOrderSetupForChildItems.ItemId   == childItems.ChildItemID && 
                           metInventItemOrderSetupForChildItems.SiteId     == childItems.InventSiteId;

                if (metInventItemOrderSetupForChildItems)
                {
                    this.updateStatusToDeleted(metInventItemOrderSetupForChildItems, _inventDim.inventDimId);
                }
            }
        }
    }

    /// <summary>
    /// To change the item site level field called Item status to 'Deleted'.
    /// </summary>
    /// <param name = "_metInventItemOrderSetup">METInventItemOrderSetup table</param>
    /// <param name = "_inventDimId">Invent Dim Id</param>
    private void updateStatusToDeleted( METInventItemOrderSetup     _metInventItemOrderSetup,
                                        InventDimId                 _inventDimId)
    {
        if (_metInventItemOrderSetup)
        {          
            ttsbegin;
            _metInventItemOrderSetup.selectForUpdate(true);
            _metInventItemOrderSetup.ItemStatus         = METConstants::Deleted;
            _metInventItemOrderSetup.DeleteStatusDate   = DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone());
            _metInventItemOrderSetup.SubrangeId         = '';
            _metInventItemOrderSetup.SubrangeDesc       = '';
            _metInventItemOrderSetup.update();
            ttscommit;

            InventItemInventSetup inventItemInventSetup     = InventItemInventSetup::find(_metInventItemOrderSetup.ItemId, _inventDimId,true);
            InventItemPurchSetup inventItemPurchSetup       = InventItemPurchSetup::find(_metInventItemOrderSetup.ItemId, _inventDimId, true);
                            
            if (inventItemInventSetup)
            {
                ttsbegin;                
                inventItemInventSetup.Stopped = true;
                inventItemInventSetup.update();
                ttscommit;
            }
            if (inventItemPurchSetup)
            {
                ttsbegin;                
                inventItemPurchSetup.Stopped = true;
                inventItemPurchSetup.update();
                ttscommit;
            }            
            
        }
    }

    /// <summary>
    /// To check whether open purchase line or transfer line exist.
    /// MPJ_22974_BMSProductMDRItemStatusAndPackChange    
    /// </summary>
    /// <param name = "_itemId">Item </param>
    /// <returns>boolean value</returns>
    private boolean isPOQtyOrTransQtyExist(ItemId _itemId)
    {
        boolean             ret;
        PurchLine           purchLine;
        InventTransferLine  inventTransferLine;
        InventTransferTable inventTransferTable;

        select firstonly RecId from purchLine
            where purchLine.ItemId == _itemId &&
                  purchLine.PurchStatus  == PurchStatus::Backorder;
        
        select firstonly RecId from inventTransferLine
            where inventTransferLine.ItemId == _itemId 
            exists join inventTransferTable
                where inventTransferTable.TransferId == inventTransferLine.TransferId && 
                inventTransferTable.TransferStatus != InventTransferStatus::Shipped;
        
        if (purchLine || inventTransferLine)
        {
            ret = true;
        }

        return ret;
    }

/// <summary>
/// To check whether physical inventory fore the item is zero
/// MPJ_22974_BMSProductMDRItemStatusAndPackChange     
/// </summary>
/// <param name = "_itemId">Item </param>
/// <param name = "_siteId">site </param>
/// <returns>boolean value</returns>
private boolean isPhysicalInventoryValueZero(ItemId _itemId, InventSiteId _siteId)
{
    boolean         ret;
    InventOnhand    inventOnhand;
    InventDim       inventDim;
    InventDimParm   inventDimParm;
    
    inventDim.InventSiteId = _siteId;
    inventDim = InventDim::findOrCreate(inventDim);
    inventDimParm.initFromInventDim(inventDim);
    inventOnhand = InventOnhand::newParameters(_itemId, inventDim, inventDimParm);
    
    if (!inventOnhand.availPhysical())
    {
        ret = true;
    }
    
    return ret;
}

    /// <summary>
    /// To change the item site level field called Item status to 'Discontinued'.
    /// </summary>
    /// <param name = "_queryRun">QueryRun</param>
    /// <param name = "_metChangeItemStatusContract">METChangeItemStatusContract</param>
    private void changeStatusToDiscontinued(QueryRun _queryRun, METChangeItemStatusContract _metChangeItemStatusContract)
    {
        
        while(_queryRun.next())
        {
            
            METInventItemOrderSetup metInventItemOrderSetup, metInventItemOrderSetupToActive, metInventItemOrderSetupToDiscontinue; 
            InventItemPurchSetup    inventItemPurchSetup;

            metInventItemOrderSetup = _queryRun.get(tableNum(METInventItemOrderSetup));

            ttsbegin;
            update_recordset metInventItemOrderSetupToDiscontinue
                setting ItemStatus = METConstants::Discontinued
                where metInventItemOrderSetupToDiscontinue.ItemId == metInventItemOrderSetup.ItemId
                    && metInventItemOrderSetupToDiscontinue.SiteId == metInventItemOrderSetup.SiteId
                    && (metInventItemOrderSetupToDiscontinue.ItemStatus != METConstants::Discontinued || metInventItemOrderSetupToDiscontinue.ItemStatus != METConstants::Deleted)
                    && (metInventItemOrderSetupToDiscontinue.DiscontinueDate != Global::DateNull()
                    || metInventItemOrderSetupToDiscontinue.DiscontinueDate <= DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone()));

            // New condition to make Item as Actice from discontinue batch job            
            update_recordset metInventItemOrderSetupToActive
                setting ItemStatus = METConstants::Active
                where metInventItemOrderSetupToActive.ItemId == metInventItemOrderSetup.ItemId
                    && metInventItemOrderSetupToActive.SiteId == metInventItemOrderSetup.SiteId
                    && metInventItemOrderSetupToActive.ItemStatus == METConstants::Discontinued
                    && (metInventItemOrderSetupToActive.DiscontinueDate == Global::DateNull() 
                    || metInventItemOrderSetupToActive.DiscontinueDate > DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone()));
            ttscommit;

            metInventItemOrderSetup.reread();

            //NS-Bug 218466: CB267 - Change Item Status batch job = Discontinued not working when the Discontinue Date field is updated to a future date or removed
            if (metInventItemOrderSetup.ItemStatus == METConstants::Discontinued)
            {
                update_recordset inventItemPurchSetup setting Override = NoYes::Yes, Stopped = NoYes::Yes
                    where inventItemPurchSetup.ItemId == metInventItemOrderSetup.ItemId
                    && inventItemPurchSetup.InventDimId == metInventItemOrderSetup.InventDimId;
            }
            else if (metInventItemOrderSetup.ItemStatus == METConstants::Active)
            {
                update_recordset inventItemPurchSetup setting Override = NoYes::No, Stopped = NoYes::No
                    where inventItemPurchSetup.ItemId == metInventItemOrderSetup.ItemId
                    && inventItemPurchSetup.InventDimId == metInventItemOrderSetup.InventDimId;
            }
            //NE-Bug 218466: CB267 - Change Item Status batch job = Discontinued not working when the Discontinue Date field is updated to a future date or removed
        }
    }

    /// <summary>
    /// This method checks if Item is Child or not
    /// </summary>
    /// <param name = "_itemId">Item Id</param>
    /// <param name = "_inventSiteId">Site Id</param>
    /// <returns>boolean</returns>
    private boolean checkIfItemIsChild(ItemId _itemId, InventSiteId _inventSiteId)
    {
        METSalesItemSubstitutionParentChild metSalesItemSubstitutionParentChild;

        select firstonly RecId
            from metSalesItemSubstitutionParentChild
            where metSalesItemSubstitutionParentChild.ChildItemID == _itemId
            && metSalesItemSubstitutionParentChild.InventSiteId == _inventSiteId;
        
        if (metSalesItemSubstitutionParentChild.RecId)
        {
            return true;
        }       

        return false;
    }

    private boolean checkIfItemIsTemp(ItemId _itemId)
    { 
        InventTable                 inventTable;
        EcoResProductAttributeValue ecoResProductAttributeValue;
        EcoResAttribute             ecoResAttribute;
        EcoResValue                 ecoResValue;        

        select firstonly ecoResValue
            exists join ecoResProductAttributeValue
            where ecoResValue.RecId == ecoResProductAttributeValue.Value
            exists join ecoResAttribute
            where ecoResProductAttributeValue.Attribute == ecoResAttribute.RecId
            && ecoResAttribute.Name == METConstants::TempItemForPackChange
            exists join inventTable
            where inventTable.itemid == _itemId
            && ecoResProductAttributeValue.Product == inventTable.Product;
       
        if (ecoResValue.value()== METConstants::Yes)
        {
            return true;
        }      

        return false;
    }

    private boolean checkIfItemIsTempItemForPackChange(ItemId _itemId)
    {
        METInventItemOrderSetup inventItemOrderSetup;

        select firstonly RecId
            from inventItemOrderSetup
            where inventItemOrderSetup.TempItemPackChg == _itemId;

        if (inventItemOrderSetup)
        {
            return true;
        }

        return false;
    }

    /// <summary>
    /// to change the item site level field called Item status to 'Active'.
    /// MPJ_22974_BMSProductMDRItemStatusAndPackChange    
    /// </summary>
    /// <param name = "_queryRun"> query to select rcords </param>
    private void changeStatusToActive(QueryRun _queryRun)
    {
        
        while(_queryRun.next())
        {            
            METInventItemOrderSetup    metInventItemOrderSetup, metInventItemOrderSetupSupplySite;
            metInventItemOrderSetup = _queryRun.get(tableNum(METInventItemOrderSetup));            
            
            if (!this.checkIfItemIsChild(metInventItemOrderSetup.ItemId, metInventItemOrderSetup.SiteId))
            {
                METReqItemTableInventDimView metReqItemTableInventDimView; 
                METItemStatusWarehouses metItemStatusWarehouses;
                
                while select ItemId, CovInventDimId, ReqPOType, InventLocationIdReqMain, VendId, MainWarehouseInventSiteId
                    from metReqItemTableInventDimView
                    where metReqItemTableInventDimView.ItemId == metInventItemOrderSetup.ItemId
                    && metReqItemTableInventDimView.InventSiteId == metInventItemOrderSetup.SiteId
                    && metReqItemTableInventDimView.ReqPOType == ReqPOType::Transfer
                    && metReqItemTableInventDimView.MainWarehouseInventSiteId != ''
                    && metReqItemTableInventDimView.MainWarehouseInventSiteId != metInventItemOrderSetup.SiteId
                    notexists join metItemStatusWarehouses
                    where metItemStatusWarehouses.InventLocationId == metReqItemTableInventDimView.InventLocationId
                {                       
                    select firstonly RecId
                        from metInventItemOrderSetupSupplySite
                        where metInventItemOrderSetupSupplySite.ItemId  == metInventItemOrderSetup.ItemId
                        && metInventItemOrderSetupSupplySite.SiteId   == metReqItemTableInventDimView.MainWarehouseInventSiteId
                        && metInventItemOrderSetupSupplySite.ItemStatus ==  METConstants::Active;                                    
                        
                    if (metInventItemOrderSetupSupplySite)
                    {
                        this.updateStatusToActive(metInventItemOrderSetup);
                        METInventItemOrderSetup::updateChildItemSiteStatus(metInventItemOrderSetup.ItemId, metInventItemOrderSetup.SiteId);
                    }                  
                    
                }
                while select ItemId, CovInventDimId, ReqPOType, InventLocationIdReqMain, VendId, VendIntercompanyWarehouse
                    from metReqItemTableInventDimView
                    where metReqItemTableInventDimView.ItemId == metInventItemOrderSetup.ItemId
                    && metReqItemTableInventDimView.InventSiteId == metInventItemOrderSetup.SiteId
                    && metReqItemTableInventDimView.ReqPOType == ReqPOType::Purch
                    && metReqItemTableInventDimView.METInterCompanySourced == NoYes::Yes
                    notexists join metItemStatusWarehouses
                    where metItemStatusWarehouses.InventLocationId == metReqItemTableInventDimView.InventLocationId
                {
                    boolean updateToActive;
                    
                    InventLocationId interCompInventLocationId = metReqItemTableInventDimView.VendIntercompanyWarehouse;

                    if (interCompInventLocationId)
                    {
                        changecompany(inventParameters.METInterCompanyPurchaseLegalEntity)
                        {
                            InventLocation inventLocationIntCom;

                            select firstonly InventSiteId from inventLocationIntCom
                            where inventLocationIntCom.InventLocationId == interCompInventLocationId;

                            if (inventLocationIntCom)
                            {
                                METInventItemOrderSetup     metInventItemOrderSetupIntCom;

                                select firstonly RecId
                                from metInventItemOrderSetupIntCom
                                where metInventItemOrderSetupIntCom.ItemId == metInventItemOrderSetup.ItemId
                                    && metInventItemOrderSetupIntCom.SiteId == inventLocationIntCom.InventSiteId
                                    && metInventItemOrderSetupIntCom.ItemStatus ==  METConstants::Active;

                                if(metInventItemOrderSetupIntCom)
                                {
                                    updateToActive = true;
                                }
                            }
                        }
                        //Update Active status in current batch job
                        if (updateToActive)
                        {
                            this.updateStatusToActive(metInventItemOrderSetup);
                            METInventItemOrderSetup::updateChildItemSiteStatus(metInventItemOrderSetup.ItemId, metInventItemOrderSetup.SiteId);
                        }
                    }                    
                }                                   
            }
        }   
    }

/// <summary>
/// Update Status method
/// </summary>
/// <param name = "_metInventItemOrderSetup">METInventItemOrderSetup</param>
/// <param name = "_status">METItemStatus</param>
public void updateStatus(METInventItemOrderSetup _metInventItemOrderSetup, METItemStatus _status)
{
    if (_metInventItemOrderSetup)
    {
        ttsbegin;
        _metInventItemOrderSetup.selectForUpdate(true);
        _metInventItemOrderSetup.ItemStatus = _status;
        _metInventItemOrderSetup.update();
        ttscommit;
    }
}

/// <summary>
/// Update status to Active
/// </summary>
/// <param name = "_metInventItemOrderSetup">METInventItemOrderSetup</param>
public void updateStatusToActive(METInventItemOrderSetup _metInventItemOrderSetup)
{
    if (_metInventItemOrderSetup)
    {
        ttsbegin;
        _metInventItemOrderSetup.selectForUpdate(true);
        _metInventItemOrderSetup.ItemStatus = METItemStatusTable::findByStatus(METItemsStatus::Active).ItemStatus;
        _metInventItemOrderSetup.PublishPriceBook = NoYes::Yes;
        _metInventItemOrderSetup.PublishPortal = NoYes::Yes;
        _metInventItemOrderSetup.PublishHost = NoYes::Yes;
        _metInventItemOrderSetup.update();
        ttscommit;
    }
}

    /// <summary>
    /// Validate NDC site
    /// </summary>
    /// <param name = "_inventLocation">InventLocation</param>
    /// <param name = "_reqItemTableRecId">RecId</param>
    /// <param name = "_itemId">ItemId</param>
    /// <returns>boolean</returns>
    private boolean changeStatusToDeleted_ValidateNDC(RecId _reqItemTableRecId, ItemId _itemId)
    {
        boolean ret = true;

        InventLocation inventLocationNDC;

        while select RecId, InventSiteId, InventLocationId
                        from inventLocationNDC
                        where inventLocationNDC.METNDCWarehouse == NoYes::Yes
        {
            ret = this.changeStatusToDeleted_Validate(inventLocationNDC, _reqItemTableRecId, _itemId);
            
            if (!ret)
            {
                return ret;
            }
        }

        return ret;
    }
